import { readFile, writeFile } from 'node:fs/promises';
import { imageLimits } from './image-attachments.mjs';

const root = new URL('./', import.meta.url);
const parts = [
  '/* Pi Voice browser bundle. Generated by: npm run build. Edit src/, not this file.\n * Includes markdown-it 15.0.3 (MIT); see vendor/markdown-it/LICENSE and UPSTREAM.md. */',
  `/* markdown-it license:\n${(await readFile(new URL('vendor/markdown-it/LICENSE', root), 'utf8')).trim()}\n*/`,
  (await readFile(new URL('vendor/markdown-it/markdown-it.min.js', root), 'utf8'))
    .replace(/^\/\/# sourceMappingURL=.*$/gm, ''),
  await readFile(new URL('src/markdown.js', root), 'utf8'),
  `globalThis.PiVoiceImageLimits = Object.freeze(${JSON.stringify(imageLimits)});`,
  await readFile(new URL('src/native-speech.js', root), 'utf8'),
  await readFile(new URL('src/playback.js', root), 'utf8'),
  await readFile(new URL('src/app.js', root), 'utf8'),
];
// Concatenate into the already-served /app.js route: frontend changes need only
// a Chrome refresh, not a Pi restart to change the backend's asset allowlist.
const bundle = `${parts.join('\n;\n').trimEnd()}\n`;
const output = new URL('public/app.js', root);
if (process.argv.includes('--check')) {
  if (await readFile(output, 'utf8') !== bundle) {
    console.error('public/app.js is stale. Run npm run build.');
    process.exitCode = 1;
  }
} else {
  await writeFile(output, bundle);
  console.log(`Built public/app.js (${Buffer.byteLength(bundle)} bytes, no external requests).`);
}
